package handlers

import (
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"strings"
	"time"
	"servicedesk/internal/auth"
	"servicedesk/internal/dto"
	"servicedesk/internal/models"
	"servicedesk/internal/services"
	"servicedesk/internal/validators"
	"github.com/gofiber/fiber/v2"
	"golang.org/x/crypto/bcrypt"
	"gorm.io/gorm"
)

type Handler struct { db *gorm.DB; tickets *services.TicketService; jwt *auth.Manager }
func New(db *gorm.DB, tickets *services.TicketService, jwt *auth.Manager) *Handler { return &Handler{db: db, tickets: tickets, jwt: jwt} }
func ErrorHandler(c *fiber.Ctx, err error) error { code := fiber.StatusInternalServerError; message := "internal server error"; var fiberError *fiber.Error; if errors.As(err, &fiberError) { code, message = fiberError.Code, fiberError.Message }; return c.Status(code).JSON(fiber.Map{"error": fiber.Map{"message": message}}) }
func userID(c *fiber.Ctx) uint { return c.Locals("userID").(uint) }

func (h *Handler) Login(c *fiber.Ctx) error { var input dto.LoginRequest; if err := c.BodyParser(&input); err != nil { return fiber.NewError(400, "invalid request body") }; var user models.User; if err := h.db.Where("email = ?", strings.ToLower(strings.TrimSpace(input.Email))).First(&user).Error; err != nil || !user.Active || bcrypt.CompareHashAndPassword([]byte(user.PasswordHash), []byte(input.Password)) != nil { return fiber.NewError(401, "invalid email or password") }; token, err := h.jwt.Create(user.ID, string(user.Role)); if err != nil { return err }; refreshToken, err := h.jwt.CreateRefresh(user.ID, string(user.Role)); if err != nil { return err }; return c.JSON(fiber.Map{"data": fiber.Map{"accessToken": token, "refreshToken": refreshToken, "user": user}}) }
func (h *Handler) Refresh(c *fiber.Ctx) error { var input dto.RefreshRequest; if err := c.BodyParser(&input); err != nil || input.RefreshToken == "" { return fiber.NewError(400, "refreshToken is required") }; claims, err := h.jwt.Parse(input.RefreshToken); if err != nil || claims.Subject != "refresh" { return fiber.NewError(401, "invalid refresh token") }; var user models.User; if err := h.db.First(&user, claims.UserID).Error; err != nil || !user.Active { return fiber.NewError(401, "user is unavailable") }; token, err := h.jwt.Create(user.ID, string(user.Role)); if err != nil { return err }; return c.JSON(fiber.Map{"data": fiber.Map{"accessToken": token, "user": user}}) }
func (h *Handler) Me(c *fiber.Ctx) error { var user models.User; if err := h.db.First(&user, userID(c)).Error; err != nil { return fiber.NewError(404, "user not found") }; return c.JSON(fiber.Map{"data": user}) }
func (h *Handler) ListCategories(c *fiber.Ctx) error { var categories []models.Category; if err := h.db.Order("name").Find(&categories).Error; err != nil { return err }; return c.JSON(fiber.Map{"data": categories}) }
func (h *Handler) CreateCategory(c *fiber.Ctx) error { role := c.Locals("role").(string); if role != string(models.RoleAdmin) { return fiber.NewError(403, "only administrators can create categories") }; var input dto.CreateCategoryRequest; if err := c.BodyParser(&input); err != nil { return fiber.NewError(400, "invalid request body") }; if err := validators.Category(input.Name); err != nil { return fiber.NewError(422, err.Error()) }; category := models.Category{Name: strings.TrimSpace(input.Name), Description: strings.TrimSpace(input.Description)}; if err := h.db.Create(&category).Error; err != nil { return fiber.NewError(409, "category already exists") }; return c.Status(201).JSON(fiber.Map{"data": category}) }
func (h *Handler) ListUsers(c *fiber.Ctx) error { role := c.Locals("role").(string); if role != string(models.RoleAdmin) && role != string(models.RoleSupervisor) { return fiber.NewError(403, "forbidden") }; var users []models.User; if err := h.db.Order("role, first_name").Find(&users).Error; err != nil { return err }; return c.JSON(fiber.Map{"data": users}) }
func (h *Handler) CreateUser(c *fiber.Ctx) error { if c.Locals("role").(string) != string(models.RoleAdmin) { return fiber.NewError(403, "only administrators can create users") }; var input dto.CreateUserRequest; if err := c.BodyParser(&input); err != nil { return fiber.NewError(400, "invalid request body") }; if strings.TrimSpace(input.FirstName) == "" || strings.TrimSpace(input.LastName) == "" || !strings.Contains(input.Email, "@") || len(input.Password) < 8 { return fiber.NewError(422, "firstName, lastName, valid email and an 8 character password are required") }; if input.Role != models.RoleUser && input.Role != models.RoleTechnician && input.Role != models.RoleSupervisor && input.Role != models.RoleAdmin { return fiber.NewError(422, "invalid role") }; hash, err := bcrypt.GenerateFromPassword([]byte(input.Password), bcrypt.DefaultCost); if err != nil { return err }; user := models.User{FirstName: strings.TrimSpace(input.FirstName), LastName: strings.TrimSpace(input.LastName), Email: strings.ToLower(strings.TrimSpace(input.Email)), PasswordHash: string(hash), Role: input.Role, Active: true}; if err := h.db.Create(&user).Error; err != nil { return fiber.NewError(409, "email already exists") }; return c.Status(201).JSON(fiber.Map{"data": user}) }
func (h *Handler) UpdateUser(c *fiber.Ctx) error { if c.Locals("role").(string) != string(models.RoleAdmin) { return fiber.NewError(403, "only administrators can update users") }; id, err := c.ParamsInt("id"); if err != nil { return fiber.NewError(400, "invalid user id") }; var user models.User; if err := h.db.First(&user, id).Error; err != nil { return fiber.NewError(404, "user not found") }; var input dto.UpdateUserRequest; if err := c.BodyParser(&input); err != nil { return fiber.NewError(400, "invalid request body") }; if input.FirstName != nil { user.FirstName = strings.TrimSpace(*input.FirstName) }; if input.LastName != nil { user.LastName = strings.TrimSpace(*input.LastName) }; if input.Active != nil { user.Active = *input.Active }; if input.Role != nil { if *input.Role != models.RoleUser && *input.Role != models.RoleTechnician && *input.Role != models.RoleSupervisor && *input.Role != models.RoleAdmin { return fiber.NewError(422, "invalid role") }; user.Role = *input.Role }; if err := h.db.Save(&user).Error; err != nil { return err }; return c.JSON(fiber.Map{"data": user}) }

func (h *Handler) ListTickets(c *fiber.Ctx) error { role := c.Locals("role").(string); if c.QueryBool("mine") { role = string(models.RoleUser) }; page := c.QueryInt("page", 1); pageSize := c.QueryInt("pageSize", 10); if page < 1 { page = 1 }; if pageSize < 1 || pageSize > 100 { pageSize = 10 }; tickets, total, err := h.tickets.List(userID(c), role, c.Query("q"), c.Query("status"), c.Query("sort"), page, pageSize); if err != nil { return err }; return c.JSON(fiber.Map{"data": tickets, "meta": fiber.Map{"total": total, "page": page, "pageSize": pageSize}}) }
func (h *Handler) GetTicket(c *fiber.Ctx) error { id, err := c.ParamsInt("id"); if err != nil { return fiber.NewError(400, "invalid ticket id") }; ticket, err := h.tickets.Get(uint(id)); if errors.Is(err, gorm.ErrRecordNotFound) { return fiber.NewError(404, "ticket not found") }; if err != nil { return err }; role := c.Locals("role").(string); if role == string(models.RoleUser) && ticket.CreatorID != userID(c) { return fiber.NewError(403, "forbidden") }; if role == string(models.RoleTechnician) && (ticket.AssigneeID == nil || *ticket.AssigneeID != userID(c)) { return fiber.NewError(403, "forbidden") }; return c.JSON(fiber.Map{"data": ticket}) }
func (h *Handler) CreateTicket(c *fiber.Ctx) error { var input dto.CreateTicketRequest; if err := c.BodyParser(&input); err != nil { return fiber.NewError(400, "invalid request body") }; if input.Priority == "" { input.Priority = models.PriorityMedium }; if err := validators.Ticket(input.Title, input.CategoryID, input.Priority); err != nil { return fiber.NewError(422, err.Error()) }; ticket, err := h.tickets.Create(userID(c), input.Title, input.Description, input.CategoryID, input.Priority); if err != nil { return fiber.NewError(422, err.Error()) }; return c.Status(201).JSON(fiber.Map{"data": ticket}) }
func (h *Handler) UpdateTicket(c *fiber.Ctx) error { id, err := c.ParamsInt("id"); if err != nil { return fiber.NewError(400, "invalid ticket id") }; ticket, err := h.tickets.Get(uint(id)); if errors.Is(err, gorm.ErrRecordNotFound) { return fiber.NewError(404, "ticket not found") }; if err != nil { return err }; var input dto.UpdateTicketRequest; if err := c.BodyParser(&input); err != nil { return fiber.NewError(400, "invalid request body") }; if input.Title != nil && len(strings.TrimSpace(*input.Title)) < 5 { return fiber.NewError(422, "title must contain at least 5 characters") }; if input.Status != nil { if err := validators.Status(*input.Status); err != nil { return fiber.NewError(422, err.Error()) } }; if input.Priority != nil { if err := validators.Ticket("valid", 1, *input.Priority); err != nil { return fiber.NewError(422, err.Error()) } }; if err := h.tickets.Update(ticket, userID(c), c.Locals("role").(string), input.Title, input.Description, input.CategoryID, input.Status, input.Priority, input.AssigneeID); err != nil { return fiber.NewError(403, err.Error()) }; return c.JSON(fiber.Map{"data": ticket}) }
func (h *Handler) AddComment(c *fiber.Ctx) error { id, err := c.ParamsInt("id"); if err != nil { return fiber.NewError(400, "invalid ticket id") }; var input dto.CreateCommentRequest; if err := c.BodyParser(&input); err != nil { return fiber.NewError(400, "invalid request body") }; if err := validators.Comment(input.Message); err != nil { return fiber.NewError(422, err.Error()) }; comment, err := h.tickets.AddComment(uint(id), userID(c), input.Message); if err != nil { return err }; return c.Status(201).JSON(fiber.Map{"data": comment}) }
func (h *Handler) ListAudit(c *fiber.Ctx) error { id, err := c.ParamsInt("id"); if err != nil { return fiber.NewError(400, "invalid ticket id") }; var logs []models.AuditLog; if err := h.db.Preload("User").Where("ticket_id = ?", id).Order("created_at desc").Find(&logs).Error; err != nil { return err }; return c.JSON(fiber.Map{"data": logs}) }
func (h *Handler) UploadAttachment(c *fiber.Ctx) error { id, err := c.ParamsInt("id"); if err != nil { return fiber.NewError(400, "invalid ticket id") }; if _, err := h.tickets.Get(uint(id)); err != nil { return fiber.NewError(404, "ticket not found") }; file, err := c.FormFile("file"); if err != nil { return fiber.NewError(422, "file is required") }; if file.Size > 10<<20 { return fiber.NewError(422, "file cannot exceed 10 MB") }; extension := strings.ToLower(filepath.Ext(file.Filename)); allowed := map[string]bool{".pdf": true, ".png": true, ".jpg": true, ".jpeg": true, ".docx": true, ".xlsx": true}; if !allowed[extension] { return fiber.NewError(422, "unsupported file type") }; path := filepath.Join("uploads", fmt.Sprintf("%d-%d%s", id, time.Now().UnixNano(), extension)); if err := c.SaveFile(file, path); err != nil { return err }; attachment := models.Attachment{TicketID: uint(id), Name: filepath.Base(file.Filename), Path: path, Size: file.Size, Type: file.Header.Get("Content-Type")}; if err := h.db.Create(&attachment).Error; err != nil { return err }; return c.Status(201).JSON(fiber.Map{"data": attachment}) }
func (h *Handler) DownloadAttachment(c *fiber.Ctx) error { id, err := c.ParamsInt("id"); if err != nil { return fiber.NewError(400, "invalid ticket id") }; attachmentID, err := c.ParamsInt("attachmentId"); if err != nil { return fiber.NewError(400, "invalid attachment id") }; var attachment models.Attachment; if err := h.db.Where("id = ? AND ticket_id = ?", attachmentID, id).First(&attachment).Error; err != nil { return fiber.NewError(404, "attachment not found") }; return c.Download(attachment.Path, attachment.Name) }
func (h *Handler) DeleteAttachment(c *fiber.Ctx) error { if c.Locals("role").(string) != string(models.RoleAdmin) && c.Locals("role").(string) != string(models.RoleSupervisor) { return fiber.NewError(403, "only supervisors can delete attachments") }; id, err := c.ParamsInt("id"); if err != nil { return fiber.NewError(400, "invalid ticket id") }; attachmentID, err := c.ParamsInt("attachmentId"); if err != nil { return fiber.NewError(400, "invalid attachment id") }; var attachment models.Attachment; if err := h.db.Where("id = ? AND ticket_id = ?", attachmentID, id).First(&attachment).Error; err != nil { return fiber.NewError(404, "attachment not found") }; if err := os.Remove(attachment.Path); err != nil && !os.IsNotExist(err) { return err }; if err := h.db.Delete(&attachment).Error; err != nil { return err }; return c.SendStatus(fiber.StatusNoContent) }
func (h *Handler) Dashboard(c *fiber.Ctx) error { byStatus := make([]struct { Status models.TicketStatus `json:"status"`; Count int64 `json:"count"` }, 0); byPriority := make([]struct { Priority models.Priority `json:"priority"`; Count int64 `json:"count"` }, 0); query := func() *gorm.DB { db := h.db.Model(&models.Ticket{}); if c.Locals("role").(string) == string(models.RoleUser) { db = db.Where("creator_id = ?", userID(c)) }; return db }; var open, closed, month int64; query().Where("status NOT IN ?", []models.TicketStatus{models.StatusClosed, models.StatusCancelled}).Count(&open); query().Where("status = ?", models.StatusClosed).Count(&closed); query().Where("created_at >= date_trunc('month', current_date)").Count(&month); query().Select("status, count(*) as count").Group("status").Scan(&byStatus); query().Select("priority, count(*) as count").Group("priority").Scan(&byPriority); return c.JSON(fiber.Map{"data": fiber.Map{"openTickets": open, "closedTickets": closed, "createdThisMonth": month, "byStatus": byStatus, "byPriority": byPriority}}) }
